#include <algorithm>
#include <vector>
TEST("sizes") {
    CHECK_EQ(formatSize(0), std::string("0 bytes")); CHECK_EQ(formatSize(1), std::string("1 byte")); CHECK_EQ(formatSize(1023), std::string("1023 bytes"));
    CHECK_EQ(formatSize(1024), std::string("1.00 KB")); CHECK_EQ(formatSize(1536), std::string("1.50 KB")); CHECK_EQ(formatSize(1100), std::string("1.07 KB"));
    CHECK_EQ(formatSize(10240), std::string("10.0 KB")); CHECK_EQ(formatSize(123456789), std::string("117 MB")); CHECK_EQ(formatSize(1048575), std::string("1023 KB"));
    CHECK_EQ(formatSize(5'000'000'000ULL), std::string("4.65 GB")); CHECK_EQ(formatSize(3ULL << 50), std::string("3072 TB"));
}
TEST("natural order") {
    CHECK(naturalLess("file2", "file10")); CHECK(!naturalLess("file10", "file2")); CHECK(naturalLess("Apple", "banana")); CHECK(naturalLess("a1", "a01"));
    CHECK(naturalLess("img", "img1")); CHECK(naturalLess("ABC", "abc")); CHECK(!naturalLess("abc", "abc")); CHECK(naturalLess("v1.9", "v1.10"));
}
TEST("sorting a folder") {
    std::vector<std::string> names{ "track10.mp3", "Track2.mp3", "track1.mp3", "notes", "Notes2", "track02.mp3" };
    std::sort(names.begin(), names.end(), naturalLess);
    CHECK_EQ(names, (std::vector<std::string>{ "notes", "Notes2", "track1.mp3", "Track2.mp3", "track02.mp3", "track10.mp3" }));
}

